async function retry(fn, times, delayMs) {
  let lastErr;
  for (let i = 1; i <= times; i++) {
    try {
      return await fn();
    } catch (e) {
      lastErr = e;
      if (i < times) await new Promise((r) => setTimeout(r, delayMs));
    }
  }
  throw lastErr;
}

function reverseString(s) {
  return s.split('').reverse().join('');
}

function countVowels(s) {
  let n = 0;
  for (const c of s.toLowerCase()) {
    if ('aeiou'.includes(c)) n += 1;
  }
  return n;
}

function sumEvens(arr) {
  return arr.filter((n) => n % 2 === 0).reduce((a, b) => a + b, 0);
}

function capitalize(s) {
  return s.split(' ').map((w) => (w ? w[0].toUpperCase() + w.slice(1) : w)).join(' ');
}

function fizzBuzz(n) {
  const out = [];
  for (let i = 1; i <= n; i++) {
    out.push(i % 15 === 0 ? 'FizzBuzz' : i % 3 === 0 ? 'Fizz' : i % 5 === 0 ? 'Buzz' : String(i));
  }
  return out;
}

function groupAnagrams(words) {
  const map = new Map();
  for (const w of words) {
    const key = w.split('').sort().join('');
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(w);
  }
  return [...map.values()];
}

function flatten(arr) {
  const out = [];
  for (const v of arr) {
    if (Array.isArray(v)) out.push(...flatten(v));
    else out.push(v);
  }
  return out;
}

function isPalindrome(s) {
  const t = s.replace(/[^a-z0-9]/gi, '').toLowerCase();
  return t === t.split('').reverse().join('');
}

function binarySearch(arr, target) {
  let lo = 0, hi = arr.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (arr[mid] === target) return mid;
    if (arr[mid] < target) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
}

